"""README PARETO block is regenerated by `just pareto-report` and matches
`pareto.json` (M6 spec DoD: "every number traceable to a report file (test
compares)"). Skips cleanly if the report has not been generated yet, but
must NOT skip once `pareto.json` exists.
"""

from __future__ import annotations

import json
import re

import pytest

from dealpoint.config import PARETO_JSON_PATH, README_PATH

pytestmark = pytest.mark.gate_m6


def _pct(x):
    return "n/a" if x is None else f"{x * 100:.1f}%"


def test_readme_pareto_block_matches_pareto_json():
    if not PARETO_JSON_PATH.exists():
        pytest.skip("data/reports/pareto.json not generated yet; run `just pareto-report`")
    if not README_PATH.exists():
        pytest.fail("README.md is missing even though pareto.json exists")

    report = json.loads(PARETO_JSON_PATH.read_text(encoding="utf-8"))
    readme = README_PATH.read_text(encoding="utf-8")

    match = re.search(
        re.escape("<!-- BEGIN PARETO -->") + r"(.*?)" + re.escape("<!-- END PARETO -->"),
        readme,
        re.DOTALL,
    )
    assert match is not None, "README.md has no BEGIN/END PARETO block"
    block = match.group(1)

    assert "budget-scaled" in block
    assert "objective" in block
    assert "not comparable" in block

    for model, m in report.get("models", {}).items():
        ga = m.get("grounded_accuracy") or {}
        n_scored = ga.get("n")
        n_cases = m.get("n_cases")
        grounded = _pct(ga.get("mean"))
        assert grounded in block, f"{model} grounded_accuracy {grounded} missing from README"
        assert f"({n_scored}/{n_cases})" in block, (
            f"{model} missing scored-n ({n_scored}/{n_cases}) denominator"
        )
        usd_per_case = m.get("usd_per_case")
        if usd_per_case is not None:
            assert f"${usd_per_case:.5f}" in block
        latency_median = m.get("latency_median_ms")
        if latency_median is not None:
            assert str(latency_median) in block

    for nr in report.get("not_run", []):
        assert nr.get("model") in block
